-- Ref https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/
-- "Smart gaps" / "No gaps when only"
-- uncomment all if you wish to use that.
-- Paired workspaces: N on main screen, N+10 on side screen, switched together by ~/.local/bin/odivm-ws
for i = 1, 9 do
    hl.workspace_rule({ workspace = tostring(i),      monitor = "HDMI-A-1", default = i == 1 })
    hl.workspace_rule({ workspace = tostring(i + 10), monitor = "HDMI-A-2", default = i == 1 })
end

-- Whatever changes a screen's workspace (keys, waybar, rofi, gestures), pull the other screen to its partner
local MAIN, SIDE = "HDMI-A-1", "HDMI-A-2"
local syncing = false
hl.on("workspace.active", function ()
    if syncing then return end
    local ws = hl.get_active_workspace()
    if not ws or ws.special or ws.id < 1 or ws.id > 19 or ws.id == 10 then return end
    local on_main = ws.monitor.name == MAIN
    if on_main ~= (ws.id < 10) then return end
    local other = hl.get_monitor(on_main and SIDE or MAIN)
    if not other then return end
    local want = on_main and ws.id + 10 or ws.id - 10
    if other.active_workspace and other.active_workspace.id == want then return end
    syncing = true
    hl.config({ cursor = { no_warps = true } })
    hl.dispatch(hl.dsp.focus({ workspace = want }))
    hl.dispatch(hl.dsp.focus({ workspace = ws.id }))
    hl.config({ cursor = { no_warps = false } })
    syncing = false
end)

