local function cycle(dir)
    return function ()
        hl.dispatch(hl.dsp.window.cycle_next(dir and { direction = dir } or nil))
        hl.dispatch(hl.dsp.window.bring_to_top())
    end
end
hl.bind("ALT + Tab",           cycle())
hl.bind(mainMod .. " + Tab",   cycle())
hl.bind("ALT + SHIFT + Tab",   cycle("prev"))
hl.bind(mainMod .. " + SHIFT + Tab", cycle("prev"))

local zoom = 1.0
local function set_zoom(z)
    return function ()
        zoom = z == 0 and 1.0 or math.max(1.0, math.min(5.0, zoom * z))
        hl.config({ cursor = { zoom_factor = zoom } })
    end
end
hl.bind(mainMod .. " + equal", set_zoom(1.25), { repeating = true })
hl.bind(mainMod .. " + plus",  set_zoom(1.25), { repeating = true })
hl.bind(mainMod .. " + minus", set_zoom(0.8),  { repeating = true })
hl.bind(mainMod .. " + 0",     set_zoom(0))

-- KDE: Meta+1..9 activates task manager entry N (pinned dock apps first, then other running apps)
local dock = {
    { class = "org.kde.dolphin",       cmd = fileManager },
    { class = "firefox",               cmd = "firefox" },
    { class = "com.mitchellh.ghostty", cmd = terminal },
    { class = "codium",                cmd = "codium" },
}
local function task_entry(n)
    return function ()
        local entries, seen = {}, {}
        for _, d in ipairs(dock) do table.insert(entries, d); seen[d.class:lower()] = true end
        for _, w in ipairs(hl.get_windows()) do
            local c = (w.class or ""):lower()
            if c ~= "" and not seen[c] then seen[c] = true; table.insert(entries, { class = w.class }) end
        end
        local e = entries[n]
        if not e then return end
        for _, w in ipairs(hl.get_windows()) do
            if (w.class or ""):lower() == e.class:lower() then
                hl.dispatch(hl.dsp.focus({ window = "address:" .. w.address }))
                return
            end
        end
        if e.cmd then hl.dispatch(hl.dsp.exec_cmd(e.cmd)) end
    end
end
for i = 1, 9 do
    hl.bind(mainMod .. " + " .. i, task_entry(i))
end

